              "legenda": "Página 1 de 1. AJUSTE DE INCONSISTÊNCIAS EM LOTE Para realizar o ajuste de inconsistências em lote basta acessar as inconsistências, clicando no ícone representativo localizado no canto superior direito, e clique em “Ver todos”. Na pagina de inconsistências, basta marcar a caixa localizada ao lado esquerdo do nome do colaborador. Selecionando as inconsistências as quais deseja tratar. Feito isso ao selecionar múltiplas inconsistências será liberado o botão , onde ao seleciona-lo será apresentada uma tela para especificar o tipo de ajuste. Após preencher os campos conforme necessidade basta confirmar para finalizar as tratativas em lote.",
